32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    public String getCustomerCode() {
61	        return this.customerCode;
62	    }
63	
64	    public void setCustomerCode(String customerCode) {
65	        this.customerCode = customerCode;
66	    }
67	
68	    /** Assign the customer code '<LAST3>-<NNNN>' for the given global owner sequence number. */
69	    public void assignCustomerCode(int sequence) {
70	        this.customerCode = getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
71	    }
72	
73	    @Transient
74	    private String householdId;
75	
76	    public String getHouseholdId() {
77	        return this.householdId;
78	    }
79	
80	    public void setHouseholdId(String householdId) {
81	        this.householdId = householdId;
82	    }
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    /** Store the email lower-cased so it is persisted and returned normalised. */
92	    public void setEmail(String email) {
93	        this.email = (email == null) ? null : email.toLowerCase();
94	    }
95	
96	    public LocalDate getRegistrationDate() {
97	        return this.registrationDate;
98	    }
99	
100	    public void setRegistrationDate(LocalDate registrationDate) {
101	        this.registrationDate = registrationDate;
